def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: a JSON‑serialisable representation of the point
    """
    # If the value is already a tuple or list, assume it contains coordinates
    if isinstance(value, (tuple, list)):
        coords = list(value)
        if len(coords) == 2:
            return {"x": coords[0], "y": coords[1]}
        if len(coords) == 3:
            return {"x": coords[0], "y": coords[1], "z": coords[2]}
        raise ValueError("Point must have 2 or 3 coordinates")

    # Try to extract x, y, z attributes (common for dataclasses, namedtuples, etc.)
    attrs = {}
    for attr in ("x", "y", "z"):
        if hasattr(value, attr):
            attrs[attr] = getattr(value, attr)
    if attrs:
        # If only x and y are present, return them; otherwise include z if present
        return attrs

    # Fallback: try to iterate over the value
    try:
        coords = list(value)
        if len(coords) == 2:
            return {"x": coords[0], "y": coords[1]}
        if len(coords) == 3:
            return {"x": coords[0], "y": coords[1], "z": coords[2]}
    except TypeError:
        pass

    raise TypeError(f"Cannot dehydrate point: {value!r}")

def keys(self):
    """
    Return the keys of the record.

    :return: list of key names
    """
    # Attempt to find a dictionary attribute that likely holds the record data.
    for attr in ('_data', '_record', 'data', 'record'):
        if hasattr(self, attr):
            value = getattr(self, attr)
            if isinstance(value, dict):
                return list(value.keys())
    # Fallback: return the instance's own attributes (excluding private ones).
    return [k for k in self.__dict__ if not k.startswith('_')]

