def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        # Expand nested sequences (lists or tuples) unless they look like an
        # implements spec (a 2-tuple).  This keeps individual interfaces and
        # implements specs intact while flattening other nested structures.
        if isinstance(item, (list, tuple)):
            if len(item) == 2:
                output.append(item)
            else:
                _normalizeargs(item, output)
        else:
            output.append(item)
    return output

def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    import os
    import sys

    # Do not attempt C optimizations on PyPy
    if hasattr(sys, "implementation"):
        if sys.implementation.name == "pypy":
            return False
    else:
        if "pypy" in sys.version.lower():
            return False

    # Respect the PURE_PYTHON environment variable
    pure_python = os.getenv("PURE_PYTHON", "").lower()
    if pure_python in ("1", "true", "yes", "on"):
        return False

    return True

