    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    from pathlib import Path

    p = Path(path)
    if not p.is_dir():
        return False

    # Required files and directories
    required_files = ['.ocfl_version', '.ocfl_root']
    required_dirs = ['.ocfl_objects']

    for f in required_files:
        if not (p / f).is_file():
            return False

    for d in required_dirs:
        if not (p / d).is_dir():
            return False

    # Validate each subdirectory in .ocfl_objects
    objects_dir = p / '.ocfl_objects'
    for sub in objects_dir.iterdir():
        if sub.is_dir():
            if not (sub / '.ocfl_version').is_file():
                return False
            # Optional: check that .ocfl_root exists inside sub
            if not (sub / '.ocfl_root').is_file():
                return False

    return True

