    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same type as self
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an InventoryValidator instance")

    # The prior version must be strictly older
    if getattr(prior, "version", None) is None or getattr(self, "version", None) is None:
        raise ValueError("Both inventories must have a 'version' attribute")
    if prior.version >= self.version:
        raise ValueError("prior version must be less than current version")

    # Ensure prior inventory is a subset of the current inventory
    prior_inv = getattr(prior, "inventory", None)
    curr_inv = getattr(self, "inventory", None)
    if prior_inv is None or curr_inv is None:
        raise ValueError("Both inventories must have an 'inventory' attribute")

    for item, qty in prior_inv.items():
        if item not in curr_inv:
            raise ValueError(f"Item '{item}' in prior inventory not present in current inventory")
        if qty > curr_inv[item]:
            raise ValueError(
                f"Quantity of item '{item}' in prior inventory ({qty}) exceeds current quantity ({curr_inv[item]})"
            )

    return True

