def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, (dict, list)):
        raise ValueError("Fixity block must be a dict or a list of dicts")
    if not isinstance(manifest_files, (set, list, tuple)):
        raise ValueError("manifest_files must be a set or list of file names")

    manifest_set = set(manifest_files)

    if isinstance(fixity, dict):
        # Expect mapping from file name to hash value
        for file_name, hash_val in fixity.items():
            if not isinstance(file_name, str) or not file_name:
                raise ValueError(f"Invalid file name in fixity: {file_name!r}")
            if file_name not in manifest_set:
                raise ValueError(f"File '{file_name}' in fixity not found in manifest")
            if not isinstance(hash_val, str) or not hash_val:
                raise ValueError(f"Invalid hash value for file '{file_name}': {hash_val!r}")
    else:  # list of dicts
        seen_files = set()
        for idx, entry in enumerate(fixity):
            if not isinstance(entry, dict):
                raise ValueError(f"Fixity entry at index {idx} must be a dict, got {type(entry).__name__}")
            if 'file' not in entry or 'hash' not in entry:
                raise ValueError(f"Fixity entry at index {idx} missing required keys: {entry}")
            file_name = entry['file']
            hash_val = entry['hash']
            if not isinstance(file_name, str) or not file_name:
                raise ValueError(f"Invalid file name in fixity entry at index {idx}: {file_name!r}")
            if file_name not in manifest_set:
                raise ValueError(f"File '{file_name}' in fixity not found in manifest")
            if file_name in seen_files:
                raise ValueError(f"Duplicate file entry in fixity: {file_name}")
            seen_files.add(file_name)
            if not isinstance(hash_val, str) or not hash_val:
                raise ValueError(f"Invalid hash value for file '{file_name}' in entry at index {idx}: {hash_val!r}")
    # If we reach here, the fixity block is considered valid
    return None

