def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not pieces:
        return ""
    # Convert all pieces to strings
    parts = [str(p) for p in pieces]
    # Helper to strip trailing zeros for pretty style
    def strip_trailing_zeros(parts):
        # Convert to ints if possible
        stripped = []
        for p in parts:
            try:
                val = int(p)
            except ValueError:
                stripped.append(p)
                continue
            stripped.append(val)
        # Remove trailing zeros
        while stripped and stripped[-1] == 0:
            stripped.pop()
        return [str(p) for p in stripped]
    if style == "full":
        return ".".join(parts)
    if style == "short":
        return ".".join(parts[:2])
    if style == "pretty":
        return ".".join(strip_trailing_zeros(parts))
    if style == "semver":
        # Ensure exactly three parts
        major = parts[0] if len(parts) > 0 else "0"
        minor = parts[1] if len(parts) > 1 else "0"
        patch = parts[2] if len(parts) > 2 else "0"
        return f"{major}.{minor}.{patch}"
    if style == "pep440":
        # Simplified: just join all parts
        return ".".join(parts)
    raise ValueError(f"Unknown style: {style}")

