    register_vcs_handler._handlers[vcs] = method
    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os
    import hashlib

    num_objects = 0
    good_objects = 0

    # Walk through the storage root directory
    for root, dirs, files in os.walk(self.storage_root):
        for filename in files:
            # Skip digest files themselves
            if filename.endswith('.digest'):
                continue

            file_path = os.path.join(root, filename)
            num_objects += 1
            is_valid = True

            # Validate that the file exists (if requested)
            if validate_objects:
                if not os.path.isfile(file_path):
                    is_valid = False
                    if show_warnings:
                        print(f"[WARN] Missing file: {file_path}")

            # Validate digest (if requested)
            if check_digests:
                digest_path = file_path + '.digest'
                if os.path.isfile(digest_path):
                    try:
                        with open(digest_path, 'r', encoding='utf-8') as df:
                            expected_digest = df.read().strip()
                        # Compute actual digest
                        hasher = hashlib.sha256()
                        with open(file_path, 'rb') as f:
                            for chunk in iter(lambda: f.read(8192), b''):
                                hasher.update(chunk)
                        actual_digest = hasher.hexdigest()
                        if actual_digest != expected_digest:
                            is_valid = False
                            if show_warnings:
                                print(f"[WARN] Digest mismatch for {file_path}: expected {expected_digest}, got {actual_digest}")
                    except Exception as exc:
                        is_valid = False
                        if show_warnings:
                            print(f"[WARN] Error checking digest for {file_path}: {exc}")
                else:
                    if show_warnings:
                        print(f"[WARN] No digest file for {file_path}")

            if is_valid:
                good_objects += 1

    return num_objects, good_objects

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    if bug_ids is None:
        return params
    # Normalize bug_ids to a list of values
    if isinstance(bug_ids, (list, tuple, set)):
        ids = list(bug_ids)
    else:
        # Accept a single value or a comma‑separated string
        if isinstance(bug_ids, str):
            ids = [bug_ids]
        else:
            ids = [bug_ids]
    # Convert to a comma‑separated string as Bugzilla expects
    ids_str = ",".join(str(i) for i in ids)
    # Add or overwrite the 'ids' key in the params dictionary
    params["ids"] = ids_str
    return params

