def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to determine if a node is a MappingNode by its tag
    def is_mapping_node(node):
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

    # Merge two nodes, handling MappingNode recursively
    def merge_nodes(existing, new):
        if is_mapping_node(existing) and is_mapping_node(new):
            merged_list = merge_mapping_lists(existing.value, new.value)
            # Create a new MappingNode with the same tag and merged value list
            return type(existing)(tag=existing.tag, value=merged_list)
        else:
            # For non-mapping nodes, the new node wins
            return new

    # Merge two lists of mapping entries (key_node, value_node)
    def merge_mapping_lists(list1, list2):
        # Build a lookup of key values to indices in list1
        index_map = {k.value: i for i, (k, _) in enumerate(list1)}
        for key_node, value_node in list2:
            key_val = key_node.value
            if key_val in index_map:
                i = index_map[key_val]
                existing_value = list1[i][1]
                merged_value = merge_nodes(existing_value, value_node)
                list1[i] = (list1[i][0], merged_value)
            else:
                list1.append((key_node, value_node))
                index_map[key_val] = len(list1) - 1
        return list1

    # Main merging logic
    result = []
    key_to_index = {}
    for key_node, value_node in nodes:
        key_val = key_node.value
        if key_val in key_to_index:
            idx = key_to_index[key_val]
            existing_key_node, existing_value_node = result[idx]
            merged_value = merge_nodes(existing_value_node, value_node)
            result[idx] = (existing_key_node, merged_value)
        else:
            result.append((key_node, value_node))
            key_to_index[key_val] = len(result) - 1
    return result

