def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base == 0:
        raise ValueError("Alphabet must not be empty")
    # Map each character in the alphabet to its numeric value
    char_to_val = {ch: i for i, ch in enumerate(alphabet)}
    result = 0
    for ch in string:
        if ch not in char_to_val:
            raise ValueError(f"Character {ch!r} not in alphabet")
        result = result * base + char_to_val[ch]
    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
