def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    def get_value(obj, key):
        if isinstance(obj, dict):
            return obj.get(key)
        return getattr(obj, key, None)

    for key in ("public", "private", "legacy"):
        if get_value(request, key):
            return True
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Check for dict-like request
    if isinstance(request, dict):
        # Common Matrix request keys
        matrix_keys = {"type", "content", "room_id", "sender", "event_id", "origin_server_ts"}
        if matrix_keys & request.keys():
            return True
        # Check for path key
        path = request.get("path") or request.get("url") or request.get("uri")
        if isinstance(path, str) and "/_matrix" in path:
            return True
    # Check for string request (e.g., raw HTTP line)
    if isinstance(request, str):
        if "/_matrix" in request:
            return True
    # Check for object with attributes
    for attr in ("path", "url", "uri", "endpoint"):
        if hasattr(request, attr):
            val = getattr(request, attr)
            if isinstance(val, str) and "/_matrix" in val:
                return True
    # Check for request with json() method
    if hasattr(request, "json") and callable(request.json):
        try:
            data = request.json()
            if isinstance(data, dict):
                if {"type", "content"} & data.keys():
                    return True
        except Exception:
            pass
    return False

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        urllib = __import__('urllib.request')
        req = urllib.Request(url, method='HEAD')
        with urllib.urlopen(req, timeout=10) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # A valid tag must:
    #   - be non-empty
    #   - contain only lowercase letters, digits, or hyphens
    #   - not start or end with a hyphen
    #   - not contain consecutive hyphens
    #   - be at most 30 characters long
    if not tag:
        return False
    if len(tag) > 30:
        return False
    # Use a simple loop to avoid external imports
    prev_char = ''
    for ch in tag:
        if ch.isupper():
            return False
        if ch == '-':
            if prev_char == '-':
                return False
            if prev_char == '':
                return False  # leading hyphen
        elif not (ch.islower() or ch.isdigit()):
            return False
        prev_char = ch
    if tag[-1] == '-':
        return False  # trailing hyphen
    return True

