def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Normalize the base URL: strip any trailing slash
    base = url.rstrip('/')
    # Default document path if not provided
    if document_path is None:
        document_path = '/nodeinfo/2.0'
    # Ensure the document path starts with a slash
    if not document_path.startswith('/'):
        document_path = '/' + document_path
    # Build the full href to the NodeInfo document
    href = f"{base}{document_path}"
    # Construct the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    result = {"subject": None, "aliases": [], "links": []}

    # Try JSON first
    try:
        data = json.loads(document)
        # JSON format
        result["subject"] = data.get("subject")
        result["aliases"] = data.get("aliases", [])
        links = data.get("links", [])
        for link in links:
            # Ensure link is a dict
            if isinstance(link, dict):
                result["links"].append({
                    "rel": link.get("rel"),
                    "type": link.get("type"),
                    "href": link.get("href")
                })
        return result
    except Exception:
        pass  # Not JSON, try XML

    # Try XRD (XML)
    try:
        root = ET.fromstring(document)
        # Namespace handling: XRD may have namespace, but we can ignore
        # Find subject
        subject_elem = root.find(".//{*}subject")
        if subject_elem is not None and subject_elem.text:
            result["subject"] = subject_elem.text.strip()
        # Find aliases
        for alias_elem in root.findall(".//{*}alias"):
            if alias_elem.text:
                result["aliases"].append(alias_elem.text.strip())
        # Find links
        for link_elem in root.findall(".//{*}link"):
            rel = link_elem.get("rel")
            type_ = link_elem.get("type")
            href = link_elem.get("href")
            # Some XRD may use <uri> inside <link>
            if href is None:
                uri_elem = link_elem.find(".//{*}uri")
                if uri_elem is not None and uri_elem.text:
                    href = uri_elem.text.strip()
            if href:
                result["links"].append({
                    "rel": rel,
                    "type": type_,
                    "href": href
                })
        return result
    except Exception:
        # If parsing fails, return empty result
        return result

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.parse
    import json

    # Normalize handle: remove leading 'acct:' if present
    if handle.startswith('acct:'):
        handle = handle[5:]

    # Ensure handle contains a domain part
    if '@' not in handle:
        return {}

    # Build the webfinger URL
    resource = urllib.parse.quote(f'acct:{handle}')
    domain = handle.split('@', 1)[1]
    url = f'https://{domain}/.well-known/webfinger?resource={resource}'

    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                return {}
            content = response.read().decode('utf-8')
            return json.loads(content)
    except Exception:
        return {}

def list_of_file_names(settings_dirs, spec_option):
    """Return a list of file names from the given directories filtered by spec_option.

    Parameters
    ----------
    settings_dirs : str or Iterable[str]
        Directory or list of directories to search.
    spec_option : str or Iterable[str] or None
        Pattern(s) to filter files, e.g. '*.ini'. If None, all files are returned.

    Returns
    -------
    list[str]
        List of file names (full paths) that match the pattern(s).
    """
    import os
    import glob

    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs)

    if spec_option is None:
        patterns = ['*']
    elif isinstance(spec_option, str):
        patterns = [spec_option]
    else:
        patterns = list(spec_option)

    result = []
    for d in dirs:
        if not os.path.isdir(d):
            continue
        for pat in patterns:
            full_pattern = os.path.join(d, pat)
            for path in glob.glob(full_pattern):
                if os.path.isfile(path):
                    result.append(path)
    return result

