@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Ensure we have content to validate
        if spec_content is None:
            raise IRValidatorException("Spec content is missing")

        # If the content is a string, attempt to parse it as YAML
        # (Assuming yaml.safe_load is available in the environment)
        if isinstance(spec_content, str):
            try:
                import yaml
                spec_content = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Failed to parse YAML content: {exc}")

        # At this point, spec_content should be a dictionary
        if not isinstance(spec_content, dict):
            raise IRValidatorException("Spec content must be a dictionary")

        # Define the mandatory fields that must be present in the spec
        required_fields = ["name", "version", "description"]

        missing_fields = [field for field in required_fields if field not in spec_content]
        if missing_fields:
            raise IRValidatorException(
                f"Missing mandatory fields in spec: {', '.join(missing_fields)}"
            )

        return spec_content

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("No YAML file path provided")

        try:
            with open(yaml_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except FileNotFoundError as e:
            raise IRValidatorException(f"File not found: {yaml_file}") from e
        except Exception as e:
            raise IRValidatorException(f"Error reading YAML file: {e}") from e

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file does not contain a mapping at the top level")

        # Determine required fields; assume the class defines a list/tuple of required keys
        required_fields = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields in YAML file: {', '.join(missing)}")

        return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Get defaults from the spec definition
    spec = getattr(self, 'spec', {})
    for name, arg_spec in spec.items():
        if isinstance(arg_spec, dict) and 'default' in arg_spec:
            defaults[name] = arg_spec['default']
    # Merge in any defaults from a config source if present
    config = getattr(self, 'config', {})
    for name, val in config.items():
        if name not in defaults:
            defaults[name] = val
    return defaults

