def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Retrieve the command object or dictionary
    command = self.commands.get(command_name)
    if command is None:
        return None

    # Determine where the options are stored
    if isinstance(command, dict):
        options = command.get("options", {})
    else:
        options = getattr(command, "options", {})

    # Return the option specification if it exists
    return options.get(argument_name) if isinstance(options, dict) else None

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # If the class does not define required arguments, nothing to validate.
    if not hasattr(self, "required_args"):
        return True

    # Ensure args is a mapping; if not, raise an informative error.
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")

    missing = [name for name in self.required_args if name not in args or args[name] is None]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        required = []
        # Ensure args is a dict for eval context
        if not isinstance(args, dict):
            try:
                args = dict(args)
            except Exception:
                args = {}
        for opt in options_spec:
            # Support both dicts and objects
            required_when = opt.get('required_when') if isinstance(opt, dict) else getattr(opt, 'required_when', None)
            if required_when is None:
                continue
            try:
                if callable(required_when):
                    match = required_when(args)
                else:
                    # Treat as a string expression; evaluate in a safe namespace
                    match = eval(required_when, {}, args)
                if match:
                    name = opt.get('name') if isinstance(opt, dict) else getattr(opt, 'name', None)
                    if name:
                        required.append(name)
            except Exception:
                # If evaluation fails, ignore this option
                continue
        return required

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments. It can be a dict mapping argument names to values,
                 a list of tuples (name, value, max_length), or a list/tuple of values
                 with corresponding max lengths defined in self.max_lengths.
    """
    # Helper to check a single value against a max length
    def _check(name, value, max_len):
        if max_len is None:
            return
        if isinstance(value, (str, bytes)):
            if len(value) > max_len:
                raise ValueError(f"Argument '{name}' exceeds maximum length of {max_len}")

    # Case 1: args is a dict of name -> value
    if isinstance(args, dict):
        max_lengths = getattr(self, 'max_lengths', {})
        for name, value in args.items():
            _check(name, value, max_lengths.get(name))
        return

    # Case 2: args is a list/tuple
    if isinstance(args, (list, tuple)):
        # Subcase 2a: list of tuples (name, value, max_len)
        if all(isinstance(item, tuple) and len(item) == 3 for item in args):
            for name, value, max_len in args:
                _check(name, value, max_len)
            return

        # Subcase 2b: list of values with max lengths defined in self.max_lengths
        max_lengths = getattr(self, 'max_lengths', [])
        if not isinstance(max_lengths, (list, tuple)):
            max_lengths = []
        for idx, value in enumerate(args):
            max_len = max_lengths[idx] if idx < len(max_lengths) else None
            _check(f"arg{idx}", value, max_len)
        return

    # If args is of an unexpected type, do nothing or raise an error
    raise TypeError("Unsupported type for args in validate_length_args")

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Determine the mapping of argument names to allowed choices.
        # It is assumed that the class has an attribute `choices` which is a
        # dictionary mapping argument names to an iterable of allowed values.
        if not hasattr(self, "choices") or not isinstance(self.choices, dict):
            # Nothing to validate if no choices mapping is defined.
            return

        # Normalize args to a dictionary if it is a Namespace or similar.
        if hasattr(args, "__dict__"):
            args_dict = vars(args)
        else:
            args_dict = args

        for arg_name, value in args_dict.items():
            if arg_name not in self.choices:
                continue  # No choice restriction for this argument.

            allowed = self.choices[arg_name]
            # If the allowed choices are not iterable, skip validation.
            if not hasattr(allowed, "__iter__"):
                continue

            # Handle None values gracefully.
            if value is None:
                continue

            # If the argument value is a collection, validate each element.
            if isinstance(value, (list, tuple, set)):
                for v in value:
                    if v not in allowed:
                        raise ValueError(
                            f"Invalid choice for argument '{arg_name}': {v}. "
                            f"Allowed choices are: {allowed}"
                        )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"Invalid choice for argument '{arg_name}': {value}. "
                        f"Allowed choices are: {allowed}"
                    )

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        :return: True if all argument values are within [self.min, self.max], False otherwise.
        """
        # If no arguments provided, consider it valid
        if args is None:
            return True

        # Determine the iterable of values to check
        if isinstance(args, dict):
            values = args.values()
        elif isinstance(args, (list, tuple, set)):
            values = args
        else:
            # Treat a single non-iterable argument as a single value
            values = [args]

        # Validate each value against the min and max bounds
        for val in values:
            try:
                if val < self.min or val > self.max:
                    return False
            except TypeError:
                # If the value cannot be compared (e.g., non-numeric), treat as invalid
                return False

        return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # A simple callable type that can be used with argparse or click.
    # It interprets the value according to the provided specifications.
    class ComplexArgumentType:
        def __init__(self, subcommand, type_name, option_name, spec_option):
            self.subcommand = subcommand
            self.type_name = type_name
            self.option_name = option_name
            self.spec_option = spec_option or {}

        def __call__(self, value):
            # If a custom parser is provided in the spec, use it.
            parser = self.spec_option.get('parser')
            if parser and callable(parser):
                return parser(value)

            # Basic type conversion based on the type_name.
            if self.type_name == 'int':
                return int(value)
            if self.type_name == 'float':
                return float(value)
            if self.type_name == 'bool':
                # Accept common boolean representations.
                if isinstance(value, bool):
                    return value
                val = str(value).lower()
                if val in ('true', '1', 'yes', 'y'):
                    return True
                if val in ('false', '0', 'no', 'n'):
                    return False
                raise ValueError(f"Invalid boolean value: {value}")

            # If choices are specified, validate against them.
            choices = self.spec_option.get('choices')
            if choices is not None:
                if value not in choices:
                    raise ValueError(f"Invalid value for {self.option_name}: {value}. "
                                     f"Expected one of {choices}")

            # Default: return the raw value (string).
            return value

        def __repr__(self):
            return (f"<ComplexArgumentType subcommand={self.subcommand!r} "
                    f"type_name={self.type_name!r} option_name={self.option_name!r} "
                    f"spec_option={self.spec_option!r}>")

    return ComplexArgumentType(subcommand, type_name, option_name, spec_option)

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: Updated dictionary
        """
        if not extra_vars:
            return vars_dict

        for var in extra_vars:
            if not isinstance(var, str):
                continue
            if '=' not in var:
                continue
            key, value = var.split('=', 1)
            # If the value contains commas, treat it as a list
            if ',' in value:
                value = [v.strip() for v in value.split(',')]
            vars_dict[key] = value

        return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Import required modules inside the function to avoid global imports
    import os
    import json

    # Determine the plugin spec file name
    spec_file = None
    for name in ("plugin.yaml", "plugin.yml", "plugin.json"):
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_file = path
            break

    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load the spec file (YAML or JSON)
    if spec_file.endswith(".json"):
        with open(spec_file, "r", encoding="utf-8") as f:
            data = json.load(f)
    else:
        try:
            import yaml
            with open(spec_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except Exception:
            # Fallback to JSON if YAML parsing fails
            with open(spec_file, "r", encoding="utf-8") as f:
                data = json.load(f)

    # Helper function to flatten nested dictionaries
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        default_path = os.path.join(os.getcwd(), 'config.yaml')
        os.environ['CONFIG_PATH'] = default_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("path and root must be strings")
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'.")
    remainder = path[len(root):]
    if remainder.startswith('/') or remainder.startswith('\\'):
        remainder = remainder[1:]
    return remainder
